-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/gold/gold_cohort_members.sql, analytics/dbt/models/gold/gold_cohorts.sql. Do not edit.
-- Gold cohorts. Diagnosis cohorts come from seed_cohort_codes, which lists codes in ICD 10, ICD 9 and
-- SNOMED CT, so one definition finds patients from all three sources whatever code system they arrived in.
-- Lab cohorts and the readmission cohort are computed from the other Gold tables.
CREATE OR REPLACE TABLE gold_cohort_members AS
SELECT DISTINCT s.cohort, c.patient_id
FROM silver_condition c
JOIN seed_cohort_codes s
  ON (s.code_system = 'icd10' AND c.icd10_code LIKE s.code_pattern)
  OR (s.code_system <> 'icd10' AND s.code_system = c.code_system AND UPPER(REPLACE(c.code, '.', '')) LIKE s.code_pattern)
UNION
SELECT 'low_sodium', o.patient_id
FROM silver_observation o
JOIN seed_key_labs k ON k.loinc = o.loinc
WHERE k.lab = 'sodium' AND o.value_num < 135 AND o.comparator IS NULL
UNION
SELECT 'aki_signal', patient_id FROM gold_aki_signal
UNION
SELECT 'readmitted_30d', patient_id FROM gold_encounter_summary WHERE readmitted_30d;

-- Gold cohort sizes by source, from gold_cohort_members. patients and records count patient records; people counts
-- persons, one per master id of gold_patient_crosswalk, so a person the EMPI linked across sources counts once. The
-- per source columns count records, since one person can have a record in several sources.
CREATE OR REPLACE TABLE gold_cohorts AS
WITH totals AS (
    SELECT COUNT(*) AS records, COUNT(DISTINCT master_id) AS people
    FROM gold_patient_crosswalk
)
SELECT
    m.cohort,
    COUNT(*)                                                    AS patients,
    SUM(CASE WHEN p.source = 'mimic' THEN 1 ELSE 0 END)         AS mimic,
    SUM(CASE WHEN p.source = 'synthea' THEN 1 ELSE 0 END)       AS synthea,
    SUM(CASE WHEN p.source = 'hl7v2' THEN 1 ELSE 0 END)         AS hl7v2,
    ROUND(100.0 * COUNT(*) / (SELECT COUNT(*) FROM silver_patient), 1) AS pct_of_patients,
    COUNT(DISTINCT COALESCE(x.master_id, m.patient_id))         AS people,
    COUNT(*)                                                    AS records,
    ROUND(100.0 * COUNT(DISTINCT COALESCE(x.master_id, m.patient_id)) / (SELECT MAX(people) FROM totals), 1) AS pct_of_people
FROM gold_cohort_members m
JOIN silver_patient p ON p.patient_id = m.patient_id
LEFT JOIN gold_patient_crosswalk x ON x.patient_id = m.patient_id
GROUP BY m.cohort;
